def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count opponent behavior
    opp_c = sum(1 for a, b in history if b == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for a, b in history if a == 'C')
    my_d = n - my_c

    # Last few moves
    last = history[-1]
    last_opp = last[1]
    last_me = last[0]

    # Defect immediately if opponent defected last round and we cooperated
    if last_opp == 'D' and last_me == 'C':
        return 'D'

    # If opponent has defected a lot, defect
    if opp_d >= 3 and opp_d * 2 >= n:
        return 'D'

    # If we've been defecting a lot and opponent still cooperates, exploit
    if opp_c >= 3 and opp_d == 0:
        # But don't be too obvious: occasionally cooperate to maintain cooperation
        if my_d <= my_c:
            return 'D'
        if n >= 10 and my_d > my_c + 2:
            if rng.random() < 0.3:
                return 'C'
            return 'D'

    # Tit-for-tat with forgiveness early
    if n <= 3:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Detect patterns: if opponent alternates or seems random, defect more
    if n >= 4:
        recent = history[-4:]
        opp_actions = [b for a, b in recent]
        # Alternating pattern
        if opp_actions == ['C', 'D', 'C', 'D'] or opp_actions == ['D', 'C', 'D', 'C']:
            return 'D'
        # All same
        if all(x == 'C' for x in opp_actions):
            # Opponent is very cooperative, exploit moderately
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        if all(x == 'D' for x in opp_actions):
            return 'D'

    # Endgame: last few rounds defect hard
    remaining = 100 - n
    if remaining <= 4:
        return 'D'

    # General: retaliate but forgive
    if last_opp == 'D':
        # Check if opponent defected before
        if opp_d >= 2:
            return 'D'
        # First defection: forgive with probability
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    # Cooperate by default, but exploit known cooperators
    if opp_d == 0 and n >= 6:
        if rng.random() < 0.25:
            return 'D'

    return 'C'
